 "content": "from collections import deque


def transform(grid):
    """Fill each enclosed zero region with a color determined by its area."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # Find zero cells connected to the grid edge; these are background.
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if out[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if out[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and out[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                q.append((nr, nc))

    # The demonstrations map enclosed areas 8, 24, and 48 to colors 8, 4, 3.
    color_by_area = {8: 8, 24: 4, 48: 3}
    seen = set(outside)
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0 or (r, c) in seen:
                continue
            region = [(r, c)]
            seen.add((r, c))
            q.append((r, c))
            while q:
                x, y = q.popleft()
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and out[nx][ny] == 0
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        region.append((nx, ny))
                        q.append((nx, ny))
            color = color_by_area[len(region)]
            for x, y in region:
                out[x][y] = color
    return out
